/**
 * server.mjs — خادم تطبيق المخزون العربي (RTL)
 * -------------------------------------------------------------
 * • يعمل بـ node:http فقط، دون أي مكتبات خارجية.
 * • قاعدة بيانات فعلية عبر node:sqlite في /tmp/inventory.sqlite
 *   (داخل حاوية Docker فقط) — لا مصفوفة في الذاكرة ولا localStorage.
 * • الجدول: stock(sku TEXT PRIMARY KEY, quantity INTEGER NOT NULL CHECK(quantity >= 0))
 * • تبدأ القاعدة فارغة تمامًا (بلا أصناف مبدئية).
 * • كل استعلامات SQL تستخدم معاملات ربط (?) ولا تُدمج القيم داخل نص SQL.
 * • عملية السحب تُنفَّذ داخل معاملة (BEGIN IMMEDIATE / COMMIT / ROLLBACK)
 *   بحيث لا يتغير أي صف إذا لم يوجد الصنف أو لم يكفِ الرصيد.
 */

import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

/* ----------------------------- الإعدادات ----------------------------- */
const DB_PATH = process.env.DB_PATH || '/tmp/inventory.sqlite'; // قاعدة فعلية داخل الحاوية
const HOST = '127.0.0.1';
const PORT = Number(process.env.PORT) || 3000;
const INDEX_PATH = join(__dirname, 'index.html');
const MAX_BODY_BYTES = 1024 * 1024; // حد أقصى لحجم الجسم: 1MB

/* ------------------------ تهيئة قاعدة البيانات ------------------------ */
mkdirSync(dirname(DB_PATH), { recursive: true });

const db = new DatabaseSync(DB_PATH);

db.exec(`
  CREATE TABLE IF NOT EXISTS stock (
    sku      TEXT PRIMARY KEY,
    quantity INTEGER NOT NULL CHECK(quantity >= 0)
  );
`);

/* ---------- استعلامات مُعدّة مسبقًا بمعاملات ربط (?) فقط ---------- */
const stmtListStock = db.prepare('SELECT sku, quantity FROM stock ORDER BY sku');
const stmtGetBySku = db.prepare('SELECT quantity FROM stock WHERE sku = ?');
const stmtInsert = db.prepare('INSERT INTO stock (sku, quantity) VALUES (?, ?)');
const stmtDecrease = db.prepare('UPDATE stock SET quantity = quantity - ? WHERE sku = ?');

/* ---------------------------- أدوات مساعدة ---------------------------- */

/** إرسال استجابة JSON مع ترميز UTF-8 */
function sendJSON(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
  });
  res.end(body);
}

/** قراءة جسم الطلب مع حد أقصى للحجم */
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        req.pause();
        reject(Object.assign(new Error('حجم الطلب كبير جدًا'), { statusCode: 413 }));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

/**
 * التحقق من صحة المدخلات:
 * sku نص غير فارغ، quantity عدد صحيح موجب (> 0).
 * أي إدخال غير صالح (نص فارغ، كمية 0 أو سالبة أو عشرية أو غير رقمية) ⇒ 400.
 */
function validatePayload(raw) {
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    return { error: 'صيغة JSON غير صالحة' };
  }
  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
    return { error: 'الجسم المرسل يجب أن يكون كائن JSON بالشكل {sku, quantity}' };
  }
  const { sku, quantity } = data;
  if (typeof sku !== 'string' || sku.trim().length === 0) {
    return { error: 'حقل sku مطلوب ويجب أن يكون نصًا غير فارغ' };
  }
  if (typeof quantity !== 'number' || !Number.isInteger(quantity) || quantity <= 0) {
    return { error: 'حقل quantity يجب أن يكون عددًا صحيحًا موجبًا' };
  }
  return { sku: sku.trim(), quantity };
}

/* --------------------------- عمليات المخزون --------------------------- */

/** إضافة صنف جديد داخل معاملة لمنع تكرار الرمز في حالة التزامن */
function addStockItem(sku, quantity) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const existing = stmtGetBySku.get(sku);
    if (existing) {
      db.exec('ROLLBACK');
      return { ok: false, status: 409, error: `الرمز «${sku}» موجود مسبقًا في المخزون` };
    }
    stmtInsert.run(sku, quantity);
    db.exec('COMMIT');
    return { ok: true, status: 201 };
  } catch (error) {
    try { db.exec('ROLLBACK'); } catch { /* لا شيء */ }
    throw error;
  }
}

/**
 * سحب كمية داخل معاملة: فحص الوجود والرصيد ثم التحديث،
 * وإرجاع 409 دون أي تغيير في البيانات عند الفشل.
 */
function withdrawStockItem(sku, quantity) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = stmtGetBySku.get(sku);
    if (!row) {
      db.exec('ROLLBACK');
      return { ok: false, status: 409, error: `الصنف «${sku}» غير موجود في المخزون` };
    }
    if (row.quantity < quantity) {
      db.exec('ROLLBACK');
      return {
        ok: false,
        status: 409,
        error: `الرصيد غير كافٍ للصنف «${sku}» (المتاح: ${row.quantity}، المطلوب: ${quantity})`,
      };
    }
    stmtDecrease.run(quantity, sku);
    db.exec('COMMIT');
    return { ok: true, status: 200 };
  } catch (error) {
    try { db.exec('ROLLBACK'); } catch { /* لا شيء */ }
    throw error;
  }
}

/** إرجاع كل الأصناف من قاعدة البيانات الفعلية */
function listStock() {
  return stmtListStock.all();
}

/* ------------------------ تقديم الصفحة الرئيسية ------------------------ */

function serveIndexPage(res) {
  try {
    const html = readFileSync(INDEX_PATH);
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store',
    });
    res.end(html);
  } catch {
    sendJSON(res, 404, { error: 'ملف index.html غير موجود بجوار server.mjs' });
  }
}

/* ------------------------------ التوجيه ------------------------------ */

const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

    // الصفحة الرئيسية: index.html
    if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
      serveIndexPage(res);
      return;
    }

    /* ----- GET /api/stock : قائمة الأصناف من قاعدة البيانات ----- */
    if (pathname === '/api/stock') {
      if (req.method === 'GET') {
        sendJSON(res, 200, { items: listStock() });
        return;
      }
      if (req.method === 'POST') {
        const parsed = validatePayload(await readBody(req));
        if (parsed.error) {
          sendJSON(res, 400, { error: parsed.error });
          return;
        }
        const result = addStockItem(parsed.sku, parsed.quantity);
        if (!result.ok) {
          sendJSON(res, result.status, { error: result.error });
          return;
        }
        sendJSON(res, 201, { message: 'تمت إضافة الصنف بنجاح', items: listStock() });
        return;
      }
      sendJSON(res, 405, { error: 'الطريقة غير مسموحة لهذا المسار' });
      return;
    }

    /* ----- POST /api/withdraw : سحب كمية داخل معاملة ----- */
    if (pathname === '/api/withdraw') {
      if (req.method === 'POST') {
        const parsed = validatePayload(await readBody(req));
        if (parsed.error) {
          sendJSON(res, 400, { error: parsed.error });
          return;
        }
        const result = withdrawStockItem(parsed.sku, parsed.quantity);
        if (!result.ok) {
          sendJSON(res, result.status, { error: result.error });
          return;
        }
        sendJSON(res, 200, { message: 'تم السحب بنجاح', items: listStock() });
        return;
      }
      sendJSON(res, 405, { error: 'الطريقة غير مسموحة لهذا المسار' });
      return;
    }

    sendJSON(res, 404, { error: 'المسار غير موجود' });
  } catch (error) {
    console.error('خطأ غير متوقع:', error);
    if (error && error.statusCode === 413) {
      req.resume();
      sendJSON(res, 413, { error: 'حجم الطلب كبير جدًا' });
      return;
    }
    if (!res.headersSent) {
      sendJSON(res, 500, { error: 'خطأ داخلي في الخادم' });
    } else {
      res.end();
    }
  }
});

server.listen(PORT, HOST, () => {
  console.log(`✅ خادم المخزون يعمل على http://${HOST}:${PORT}`);
  console.log(`🗄️  قاعدة البيانات الفعلية: ${DB_PATH}`);
});

/* --------------------------- إيقاف نظيف --------------------------- */
function shutdown() {
  server.close(() => {
    try { db.close(); } catch { /* لا شيء */ }
    process.exit(0);
  });
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

/**
 * server.mjs — خادم تطبيق المخزون العربي (RTL)
 * مكتبات مدمجة فقط: node:http + node:sqlite (+ node:fs / node:url للقراءة)
 * يستمع على 127.0.0.1:3000 ويقدّم index.html كصفحة رئيسية.
 * قاعدة SQLite فعلية في /tmp/inventory.sqlite (بيانات التشغيل داخل حاوية Docker فقط).
 * لا مصفوفة ذاكرة ولا localStorage — القاعدة هي مصدر الحقيقة الوحيد.
 */

import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const HOST = '127.0.0.1';
const PORT = 3000;
const DB_PATH = '/tmp/inventory.sqlite';

// التأكد من وجود مجلد بيانات التشغيل (داخل الحاوية: /tmp) — لا يمس ملفات المصدر
mkdirSync('/tmp', { recursive: true });

// فتح قاعدة SQLite فعلية على القرص
const db = new DatabaseSync(DB_PATH);

// إنشاء جدول stock عند بدء التشغيل — يبدأ بلا أي أصناف مبدئية
db.exec(`
  CREATE TABLE IF NOT EXISTS stock (
    sku TEXT PRIMARY KEY,
    quantity INTEGER NOT NULL CHECK(quantity >= 0)
  )
`);

// استعلامات مُجهّزة بمعاملات ربط (?) — لا تُدمج أي قيمة داخل نص SQL مطلقًا
const stmtList = db.prepare('SELECT sku, quantity FROM stock ORDER BY sku');
const stmtGet = db.prepare('SELECT sku, quantity FROM stock WHERE sku = ?');
const stmtInsert = db.prepare('INSERT INTO stock (sku, quantity) VALUES (?, ?)');
const stmtWithdraw = db.prepare('UPDATE stock SET quantity = quantity - ? WHERE sku = ?');

/* ---------- أدوات مساعدة ---------- */

function sendJson(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
  });
  res.end(body);
}

function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 100000) {
        reject(new Error('payload-too-large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      if (raw.trim() === '') {
        resolve(undefined);
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error('invalid-json'));
      }
    });
    req.on('error', reject);
  });
}

// التحقق من الإدخال: رمز نصي غير فارغ + كمية عدد صحيح موجب، وإلا null (=> 400)
function parseInput(body) {
  if (body === undefined || body === null || typeof body !== 'object' || Array.isArray(body)) return null;
  const { sku, quantity } = body;
  if (typeof sku !== 'string') return null;
  const skuTrimmed = sku.trim();
  if (skuTrimmed.length === 0) return null;
  if (!Number.isInteger(quantity) || quantity <= 0) return null;
  return { sku: skuTrimmed, quantity };
}

function isUniqueViolation(err) {
  return Boolean(err) && (
    err.code === 'SQLITE_CONSTRAINT_PRIMARYKEY' ||
    (typeof err.message === 'string' && err.message.includes('UNIQUE constraint failed'))
  );
}

/* ---------- نقاط النهاية ---------- */

async function handleApi(req, res, pathname) {
  // GET /api/stock — يعيد {items:[{sku,quantity}]} من القاعدة
  if (pathname === '/api/stock' && req.method === 'GET') {
    const items = stmtList.all();
    sendJson(res, 200, { items });
    return;
  }

  // POST /api/stock — ينشئ صنفًا برصيد صحيح موجب ويرجع 201، و409 عند تكرار الرمز
  if (pathname === '/api/stock' && req.method === 'POST') {
    let body;
    try {
      body = await readJsonBody(req);
    } catch {
      sendJson(res, 400, { error: 'صيغة الطلب غير صالحة' });
      return;
    }

    const input = parseInput(body);
    if (!input) {
      sendJson(res, 400, { error: 'الرمز مطلوب، والكمية يجب أن تكون عددًا صحيحًا موجبًا' });
      return;
    }

    if (stmtGet.get(input.sku)) {
      sendJson(res, 409, { error: 'الرمز موجود مسبقًا في المخزون' });
      return;
    }

    try {
      stmtInsert.run(input.sku, input.quantity);
    } catch (err) {
      if (isUniqueViolation(err)) {
        sendJson(res, 409, { error: 'الرمز موجود مسبقًا في المخزون' });
      } else {
        sendJson(res, 500, { error: 'خطأ في الخادم' });
      }
      return;
    }
    sendJson(res, 201, { sku: input.sku, quantity: input.quantity });
    return;
  }

  // POST /api/withdraw — سحب كمية داخل معاملة (transaction)؛ 409 عند عدم وجود الصنف
  // أو عدم كفاية الرصيد، دون أي تغيير في البيانات (ROLLBACK).
  if (pathname === '/api/withdraw' && req.method === 'POST') {
    let body;
    try {
      body = await readJsonBody(req);
    } catch {
      sendJson(res, 400, { error: 'صيغة الطلب غير صالحة' });
      return;
    }

    const input = parseInput(body);
    if (!input) {
      sendJson(res, 400, { error: 'الرمز مطلوب، والكمية يجب أن تكون عددًا صحيحًا موجبًا' });
      return;
    }

    try {
      db.exec('BEGIN IMMEDIATE');
      const row = stmtGet.get(input.sku);
      if (!row || row.quantity < input.quantity) {
        db.exec('ROLLBACK'); // رفض العملية دون تغيير البيانات
        sendJson(res, 409, {
          error: !row ? 'الصنف غير موجود في المخزون' : 'الرصيد غير كافٍ لإتمام السحب'
        });
        return;
      }
      stmtWithdraw.run(input.quantity, input.sku);
      db.exec('COMMIT');
      const updated = stmtGet.get(input.sku);
      sendJson(res, 200, { sku: updated.sku, quantity: updated.quantity });
    } catch (err) {
      try { db.exec('ROLLBACK'); } catch { /* لا معاملة مفتوحة */ }
      sendJson(res, 500, { error: 'خطأ في الخادم' });
    }
    return;
  }

  if (pathname === '/api/stock' || pathname === '/api/withdraw') {
    sendJson(res, 405, { error: 'الطريقة غير مدعومة لهذا المسار' });
    return;
  }
  sendJson(res, 404, { error: 'المسار غير موجود' });
}

/* ---------- تقديم index.html كصفحة رئيسية ---------- */

const INDEX_PATH = fileURLToPath(new URL('./index.html', import.meta.url));

async function serveIndex(res) {
  try {
    const html = await readFile(INDEX_PATH);
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store'
    });
    res.end(html);
  } catch {
    res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('index.html غير موجود بجانب server.mjs');
  }
}

/* ---------- الخادم ---------- */

const server = createServer(async (req, res) => {
  let pathname;
  try {
    pathname = new URL(req.url, `http://${HOST}:${PORT}`).pathname;
  } catch {
    sendJson(res, 400, { error: 'طلب غير صالح' });
    return;
  }

  try {
    if (pathname.startsWith('/api/')) {
      await handleApi(req, res, pathname);
      return;
    }
    if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
      await serveIndex(res);
      return;
    }
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('غير موجود');
  } catch {
    if (!res.headersSent) sendJson(res, 500, { error: 'خطأ في الخادم' });
    else res.end();
  }
});

server.listen(PORT, HOST, () => {
  console.log(`خادم المخزون يعمل على http://${HOST}:${PORT} — قاعدة البيانات: ${DB_PATH}`);
});

